import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const LOGO_HOLD = 75;
const FLIP_DURATION = 35;
const SCENE_DURATION = LOGO_HOLD + FLIP_DURATION;

const LOGOS = [
  { src: staticFile("assets/logos/Cusror_Logo.png"), label: "Cursor", color: "#00CFFF" },
  { src: staticFile("assets/logos/Claude_Logo.svg"), label: "Claude", color: "#FF8C42" },
  { src: staticFile("assets/logos/Antigravity_Logo.png"), label: "Antigravity", color: "#A78BFA" },
  { src: staticFile("assets/logos/Codex_Logo.png"), label: "Codex", color: "#10B981" },
];

export const durationInFrames =
  LOGOS.length * SCENE_DURATION - (LOGOS.length - 1) * FLIP_DURATION;

const LogoCard: React.FC<{
  logo: (typeof LOGOS)[number];
  isFirst: boolean;
  isLast: boolean;
}> = ({ logo, isFirst, isLast }) => {
  const frame = useCurrentFrame();
  const { fps: f, durationInFrames: dur } = useVideoConfig();

  // ENTER: card flips in on X axis (tumble from top)
  const enterProgress = spring({
    frame,
    fps: f,
    delay: 0,
    config: { damping: 120, stiffness: 180, mass: 0.8 },
  });

  // EXIT: card flips out downward
  const exitStart = dur - FLIP_DURATION;
  const exitProgress = isLast
    ? 0
    : interpolate(frame, [exitStart, dur], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });

  // Entry: flip from -180deg → 0 on X (tumble in from above)
  const enterRotX = isFirst ? 0 : interpolate(enterProgress, [0, 1], [-180, 0]);
  // Exit: flip out to +180deg downward
  const exitRotX = isLast ? 0 : interpolate(exitProgress, [0, 1], [0, 180]);
  const rotateX = enterRotX + exitRotX;

  // Z spin on entry for extra flair
  const enterRotZ = isFirst ? 0 : interpolate(enterProgress, [0, 1], [-15, 0]);
  const exitRotZ = isLast ? 0 : interpolate(exitProgress, [0, 1], [0, 15]);
  const rotateZ = enterRotZ + exitRotZ;

  // Scale: bouncy entry
  const entryScale = isFirst ? 1 : interpolate(enterProgress, [0, 0.4, 0.75, 1], [0.4, 1.18, 0.95, 1]);
  const exitScale = isLast ? 1 : interpolate(exitProgress, [0, 0.5, 1], [1, 1.1, 0.3]);
  const finalScale = entryScale * exitScale;

  // Opacity
  const entryOpacity = isFirst ? 1 : interpolate(enterProgress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });
  const exitOpacity = isLast ? 1 : interpolate(exitProgress, [0.5, 1], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const finalOpacity = entryOpacity * exitOpacity;

  // Glow pulse: pulses after settling
  const glowPulse = spring({
    frame,
    fps: f,
    delay: isFirst ? 10 : 25,
    config: { damping: 80, stiffness: 60 },
  });
  const glowSize = interpolate(glowPulse, [0, 1], [0, 120]);
  const glowOpacity = interpolate(glowPulse, [0, 0.3, 1], [0, 0.7, 0.25]);

  // Label slide up
  const labelProgress = spring({
    frame,
    fps: f,
    delay: isFirst ? 8 : 30,
    config: { damping: 140, stiffness: 200 },
  });
  const labelY = interpolate(labelProgress, [0, 1], [40, 0]);
  const labelOpacity = interpolate(labelProgress, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const labelExitOpacity = isLast ? 1 : interpolate(exitProgress, [0.3, 0.8], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Idle float animation (oscillates while held)
  const floatY = interpolate(
    frame,
    [0, dur],
    [0, dur * 2 * Math.PI],
    { extrapolateRight: "clamp" }
  );
  // Simple sine-based float using frame directly
  const floatOffset = Math.sin((frame / dur) * Math.PI * 2) * 8;

  // Ring rotation
  const ringRotation = interpolate(frame, [0, dur], [0, 360], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
        perspective: "1400px",
      }}
    >
      {/* Glow orb behind logo */}
      <div
        style={{
          position: "absolute",
          width: glowSize * 4,
          height: glowSize * 4,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${logo.color}55 0%, ${logo.color}00 70%)`,
          opacity: glowOpacity * finalOpacity,
          transform: `translateY(${floatOffset}px)`,
          pointerEvents: "none",
        }}
      />

      {/* Spinning ring around logo */}
      <div
        style={{
          position: "absolute",
          width: 620,
          height: 620,
          borderRadius: "50%",
          border: `3px solid ${logo.color}`,
          opacity: glowOpacity * 0.5 * finalOpacity,
          transform: `translateY(${floatOffset}px) rotate(${ringRotation}deg)`,
          boxShadow: `0 0 24px 4px ${logo.color}66`,
          borderStyle: "dashed",
          pointerEvents: "none",
        }}
      />

      {/* Second counter-rotating ring */}
      <div
        style={{
          position: "absolute",
          width: 680,
          height: 680,
          borderRadius: "50%",
          border: `1.5px solid ${logo.color}44`,
          opacity: glowOpacity * 0.3 * finalOpacity,
          transform: `translateY(${floatOffset * 0.5}px) rotate(${-ringRotation * 0.6}deg)`,
          pointerEvents: "none",
        }}
      />

      {/* Logo + flip transform */}
      <div
        style={{
          opacity: finalOpacity,
          transform: `translateY(${floatOffset}px) rotateX(${rotateX}deg) rotateZ(${rotateZ}deg) scale(${finalScale})`,
          transformStyle: "preserve-3d",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 32,
          willChange: "transform, opacity",
        }}
      >
        {/* Logo image */}
        <div
          style={{
            position: "relative",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <Img
            src={logo.src}
            style={{
              width: 480,
              height: 480,
              objectFit: "contain",
              filter: `drop-shadow(0 0 32px ${logo.color}88)`,
            }}
          />
        </div>

        {/* Label */}
        <div
          style={{
            opacity: labelOpacity * labelExitOpacity,
            transform: `translateY(${labelY}px)`,
            fontSize: 56,
            fontWeight: 700,
            fontFamily: "'Inter', sans-serif",
            color: "#ffffff",
            letterSpacing: "0.12em",
            textTransform: "uppercase",
            textShadow: `0 0 30px ${logo.color}cc, 0 2px 8px rgba(0,0,0,0.4)`,
          }}
        >
          {logo.label}
        </div>

        {/* Color accent underline */}
        <div
          style={{
            opacity: labelOpacity * labelExitOpacity,
            transform: `translateY(${labelY}px) scaleX(${labelProgress})`,
            width: 200,
            height: 4,
            borderRadius: 2,
            background: `linear-gradient(90deg, transparent, ${logo.color}, transparent)`,
            marginTop: -16,
          }}
        />
      </div>

      {/* Corner accent dots */}
      {[[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([dx, dy], i) => {
        const dotProgress = spring({
          frame,
          fps: f,
          delay: (isFirst ? 5 : 35) + i * 8,
          config: { damping: 160, stiffness: 200 },
        });
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              width: 12,
              height: 12,
              borderRadius: "50%",
              backgroundColor: logo.color,
              opacity: dotProgress * finalOpacity * 0.7,
              transform: `translate(${dx * 340}px, ${dy * 340}px) scale(${dotProgress})`,
              boxShadow: `0 0 12px 4px ${logo.color}88`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {LOGOS.map((logo, i) => (
        <React.Fragment key={logo.label}>
          <TransitionSeries.Sequence durationInFrames={SCENE_DURATION}>
            <LogoCard
              logo={logo}
              isFirst={i === 0}
              isLast={i === LOGOS.length - 1}
            />
          </TransitionSeries.Sequence>
          {i < LOGOS.length - 1 && (
            <TransitionSeries.Transition
              presentation={fade()}
              timing={linearTiming({ durationInFrames: FLIP_DURATION })}
            />
          )}
        </React.Fragment>
      ))}
    </TransitionSeries>
  );
};

export default MainComposition;
